mapper.select:
select * from (SELECT c.CREATED_BY, p.EXCEPT_DESC, p.MAINTAIN_FREQUENCY_CONTENT, p.CHECK_FREQUENCY_CONTENT, p.MAINTAIN_WORKER, p.PRACTICE_QUALIFY, c.contract_name, c.contract_number, c.project_id, p.lease_inspect_date, p.prj_lease_id, p.lease_inspect_number, p.lease_inspect_status, p.approve_status, p.LEASE_EXCEPT_FLAG, p.LEASE_QUALITY_DESC, p.PRODUCE_DESC, p.WORK_TYPE, p.WORKER_NUM, p.WORK_HOURS, p.SYSTEM_MADE_FLAG, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'LEASE_RULE_MAKE' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= p.SYSTEM_MADE_FLAG ) SYSTEM_MADE_FLAG_N, p.LEASE_IN_PLACE, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'LEASE_IN_PLACE' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= p.LEASE_IN_PLACE ) LEASE_IN_PLACE_N, p.EQUIP_SAFE_FLAG, p.CONCLUSION_SUGGEST, p.PRODUCER_SAFE_EQUIP, p.STOP_FREQUENCY_CONTENT, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'HLS.WORK_FLOW_STATUS' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= p.approve_status ) approve_status_n, (SELECT em.name FROM fnd_employee em WHERE em.employee_id = p.user_id) user_id_n,
CASE WHEN c.BUSINESS_TYPE in('T+N_LEASE_FACTORING','T+0_LEASE_FACTORING') THEN ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE c.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'RECEIVABLE_DEBTOR' ) WHEN c.BUSINESS_TYPE in('LEASE_WITHOUT_RECOURSE_IN','OPERATING_LEASE_WITHOUT_RECOURSE_IN') THEN ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE c.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'ASSET_TRANSFEROR' ) ELSE ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE c.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'TENANT' ) END AS bp_id_n,
(select pi.insure_number from prj_project_insure pi where pi.insure_id = (select max(pii.insure_id)from prj_project_insure pii where pii.project_id = p.project_id))insure_number, (select pi.INSURE_CATEGORY from prj_project_insure pi where pi.insure_id = (select max(pii.insure_id)from prj_project_insure pii where pii.project_id = p.project_id))INSURE_CATEGORY, (select pi.INSURE_END_DATE from prj_project_insure pi where pi.insure_id = (select max(pii.insure_id)from prj_project_insure pii where pii.project_id = p.project_id))INSURE_END_DATE, (select pi.INSURED_STATUS from prj_project_insure pi where pi.insure_id = (select max(pii.insure_id)from prj_project_insure pii where pii.project_id = p.project_id))INSURED_STATUS, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb. CODE = 'INSURE_STATUS' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb. VALUE = (select pi.INSURED_STATUS from prj_project_insure pi where pi.insure_id = (select max(pii.insure_id)from prj_project_insure pii where pii.project_id = p.project_id)) ) INSURED_STATUS_N, p.authority_rule_string, p.REMARKS, p.user_id as inspect_created_by, c.host_project_manager FROM prj_project c, prj_lease_inspect p WHERE c.project_id = p.project_id) t
1=1
and (t.created_by = #{request.userId} or t.inspect_created_by = #{request.userId} or t.host_project_manager = #{request.userId} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}))
AND t.project_id = #{projectId}
AND t.prj_lease_id = #{prjLeaseId}
AND t.lease_inspect_number = #{leaseInspectNumber}
AND t.lease_inspect_date = #{leaseInspectDate}
AND t.approve_status = #{approveStatus}
AND t.CONTRACT_NUMBER = #{contractNumber}
and t.LEASE_INSPECT_DATE >= #{leaseInspectDateFrom}
and t.LEASE_INSPECT_DATE <= #{leaseInspectDateTo}
order by t.PRJ_LEASE_ID desc
